/**
 * Regenerates src/data/worldMap.js — a bundled, offline-safe world coastline
 * outline for the Briefing route map (BriefingView.jsx).
 *
 *   node scripts/generate-worldmap.mjs
 *
 * Source: world-atlas's land-110m.json (Natural Earth 1:110m land polygons,
 * public domain), fetched via unpkg so no dependency is added to the repo —
 * this script only runs at generation time, its output is the runtime asset.
 *
 * Projects every coastline point with the same equirectangular formula
 * BriefingView.jsx uses for airport markers (see projectLatLng in the
 * generated file), so the coastline and the plotted route always agree.
 */
import { writeFileSync } from 'node:fs'

const TOPOJSON_URL = 'https://unpkg.com/world-atlas@2/land-110m.json'

// Must match the projectLatLng() written into the output file below.
const MAP_WIDTH  = 900
const MAP_HEIGHT = 450
function project(lon, lat) {
  const x = (lon + 180) / 360 * MAP_WIDTH
  const y = (90 - lat) / 180 * MAP_HEIGHT
  return [Math.round(x), Math.round(y)]
}

// Below this bounding-box area (in projected units — the whole world is
// 900x450), a polygon is a speck too small to read on a small cockpit map
// and just bloats the bundle — drop it.
const MIN_POLYGON_AREA = 4

// ── TopoJSON arc decoding (delta + quantized integer coordinates) ──────────
function decodeArcs(topology) {
  const { scale, translate } = topology.transform
  return topology.arcs.map(arc => {
    let x = 0, y = 0
    return arc.map(([dx, dy]) => {
      x += dx; y += dy
      return [translate[0] + scale[0] * x, translate[1] + scale[1] * y]
    })
  })
}

// arcIndex >= 0 → arcs[arcIndex] as-is; arcIndex < 0 → arcs[~arcIndex] reversed
// (TopoJSON's bitwise-NOT convention for a reused arc walked backwards).
function ringPoints(decodedArcs, arcIndexes) {
  const points = []
  for (const idx of arcIndexes) {
    const reversed = idx < 0
    const arc = decodedArcs[reversed ? ~idx : idx]
    const pts = reversed ? [...arc].reverse() : arc
    // Consecutive arcs in a ring share an endpoint — drop it to avoid a
    // zero-length duplicate segment in the path.
    points.push(...(points.length ? pts.slice(1) : pts))
  }
  return points
}

async function main() {
  const topology = await fetch(TOPOJSON_URL).then(r => r.json())
  const decodedArcs = decodeArcs(topology)

  const subpaths = []
  for (const geom of topology.objects.land.geometries) {
    const polygons = geom.type === 'Polygon' ? [geom.arcs] : geom.arcs // MultiPolygon: arcs = [polygon, ...]
    for (const polygon of polygons) {
      for (const ring of polygon) {
        const pts = ringPoints(decodedArcs, ring).map(([lon, lat]) => project(lon, lat))
        if (pts.length < 3) continue
        const xs = pts.map(p => p[0]), ys = pts.map(p => p[1])
        const area = (Math.max(...xs) - Math.min(...xs)) * (Math.max(...ys) - Math.min(...ys))
        if (area < MIN_POLYGON_AREA) continue
        subpaths.push('M' + pts.map(p => p.join(',')).join('L') + 'Z')
      }
    }
  }

  const path = subpaths.join('')

  const out = `// AUTO-GENERATED by scripts/generate-worldmap.mjs — do not edit by hand.
// Natural Earth 1:110m land polygons (public domain), via world-atlas.
// Regenerate: node scripts/generate-worldmap.mjs

// Equirectangular projection — same formula used to bake WORLD_LAND_PATH,
// so airport markers and the coastline always line up. Coordinates are in
// an 0-${MAP_WIDTH} x 0-${MAP_HEIGHT} SVG viewBox (whole world).
export function projectLatLng(lat, lng) {
  const x = (lng + 180) / 360 * ${MAP_WIDTH}
  const y = (90 - lat) / 180 * ${MAP_HEIGHT}
  return { x, y }
}

export const WORLD_MAP_WIDTH = ${MAP_WIDTH}
export const WORLD_MAP_HEIGHT = ${MAP_HEIGHT}

export const WORLD_LAND_PATH = ${JSON.stringify(path)}
`

  writeFileSync(new URL('../src/data/worldMap.js', import.meta.url), out)
  console.log(`Wrote src/data/worldMap.js (${(path.length / 1024).toFixed(1)} KB path data, ${subpaths.length} subpaths)`)
}

main().catch(e => { console.error(e); process.exit(1) })
